import type { FinderPokemon, FinderStats } from '../types/pokemon'
import { formatName } from './format'

/*
 * The Pokémon Finder matching engine.
 *
 * Everything here runs locally against the dataset generated by
 * `npm run data` — there is no AI service, no API key and no network call at
 * search time. A written description is parsed into structured "signals"
 * (types, colour, shape, size, abilities, features, keywords, …) and each
 * Pokémon is scored by how many signals it satisfies. Higher scores mean a
 * better match, and each match carries the reasons it ranked.
 */

export type StatKey = keyof FinderStats

export interface SizeConstraint {
  axis: 'height' | 'weight'
  dir: 'high' | 'low'
}

export interface StatConstraint {
  stat: StatKey
  dir: 'high' | 'low'
}

export type Legend = 'legendary' | 'mythical' | 'baby' | null

/** The accumulated intent behind a conversation, rebuilt from every message. */
export interface FinderSignals {
  numbers: number[]
  types: string[]
  excludeTypes: string[]
  color: string | null
  altColors: string[]
  excludeColors: string[]
  shapes: string[]
  excludeShapes: string[]
  features: string[]
  keywords: string[]
  excludeKeywords: string[]
  legend: Legend
  rare: boolean
  generation: number | null
  habitat: string | null
  size: SizeConstraint[]
  stats: StatConstraint[]
  rawTokens: string[]
}

export interface FinderMatch {
  pokemon: FinderPokemon
  score: number
  reasons: string[]
}

export function createSignals(): FinderSignals {
  return {
    numbers: [],
    types: [],
    excludeTypes: [],
    color: null,
    altColors: [],
    excludeColors: [],
    shapes: [],
    excludeShapes: [],
    features: [],
    keywords: [],
    excludeKeywords: [],
    legend: null,
    rare: false,
    generation: null,
    habitat: null,
    size: [],
    stats: [],
    rawTokens: [],
  }
}

/* ==========================================================================
   Vocabulary
   ========================================================================== */

type SignalKind =
  | 'type'
  | 'color'
  | 'shape'
  | 'feature'
  | 'size'
  | 'stat'
  | 'legend'
  | 'rare'
  | 'generation'
  | 'habitat'

interface SignalDef {
  kind: SignalKind
  value: string
}

/* A phrase can carry several meanings — "green" is both the grass type and the
   green Pokédex colour — so each phrase maps to a list of definitions. */
const SIGNALS = new Map<string, SignalDef[]>()

function define(kind: SignalKind, value: string, phrases: string[]) {
  for (const raw of phrases) {
    const phrase = normalize(raw)
    if (!phrase) continue
    const existing = SIGNALS.get(phrase)
    if (existing) existing.push({ kind, value })
    else SIGNALS.set(phrase, [{ kind, value }])
  }
}

