/* ==========================================================================
   Text helpers
   ========================================================================== */

export function normalize(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/-/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

export function singular(word: string): string {
  if (word.endsWith('ies') && word.length > 4) return `${word.slice(0, -3)}y`
  if (word.endsWith('ses') && word.length > 4) return word.slice(0, -2)
  if (word.endsWith('es') && word.length > 4) return word.slice(0, -2)
  if (word.endsWith('s') && !word.endsWith('ss') && word.length > 3) return word.slice(0, -1)
  return word
}

/* ==========================================================================
   Parsing a message into signals
   ========================================================================== */

function isNegated(tokens: string[], index: number): boolean {
  for (let back = 1; back <= 3 && index - back >= 0; back += 1) {
    if (NEGATORS.has(tokens[index - back])) return true
  }
  return false
}

function pushUnique<T>(list: T[], value: T) {
  if (!list.includes(value)) list.push(value)
}

function dispatch(def: SignalDef, negated: boolean, out: FinderSignals) {
  switch (def.kind) {
    case 'type':
      pushUnique(negated ? out.excludeTypes : out.types, def.value)
      break
    case 'color':
      if (negated) pushUnique(out.excludeColors, def.value)
      else if (out.color === null) out.color = def.value
      else pushUnique(out.altColors, def.value)
      break
    case 'shape':
      pushUnique(negated ? out.excludeShapes : out.shapes, def.value)
      break
    case 'feature':
      pushUnique(negated ? out.excludeKeywords : out.features, def.value)
      break
    case 'size': {
      const [axis, dir] = def.value.split(':') as ['height' | 'weight', 'high' | 'low']
      const flipped: 'high' | 'low' = negated ? (dir === 'high' ? 'low' : 'high') : dir
      const existing = out.size.find((entry) => entry.axis === axis)
      if (existing) existing.dir = flipped
      else out.size.push({ axis, dir: flipped })
      break
    }
    case 'stat': {
      const [stat, dir] = def.value.split(':') as [StatKey, 'high' | 'low']
      const flipped: 'high' | 'low' = negated ? (dir === 'high' ? 'low' : 'high') : dir
      const existing = out.stats.find((entry) => entry.stat === stat)
      if (existing) existing.dir = flipped
      else out.stats.push({ stat, dir: flipped })
      break
    }
    case 'legend':
      if (!negated) out.legend = def.value as Exclude<Legend, null>
      break
    case 'rare':
      if (!negated) out.rare = true
      break
    case 'generation':
      if (!negated) out.generation = Number(def.value)
      break
    case 'habitat':
      if (!negated) out.habitat = def.value
      break
  }
}

/** Turns one message into a fresh set of signals (a per-message delta). */
export function parseQuery(raw: string): FinderSignals {
  const out = createSignals()
  const norm = normalize(raw)
  if (!norm) return out

  const tokens = norm.split(' ').filter(Boolean)
  const consumed = tokens.map(() => false)

  /* "gen 3" / "generation three" is a two-word generation reference. */
  for (let i = 0; i < tokens.length - 1; i += 1) {
    if (tokens[i] !== 'gen' && tokens[i] !== 'generation') continue
    const next = tokens[i + 1]
    const numeric = /^\d{1,2}$/.test(next) ? Number(next) : GENERATION_ORDINALS.indexOf(next) + 1
    if (numeric >= 1 && numeric <= 9) {
      out.generation = numeric
      consumed[i] = true
      consumed[i + 1] = true
    }
  }

  /* Longest-phrase wins, so "lightning rod" is not read as two words. */
  for (let i = 0; i < tokens.length; i += 1) {
    if (consumed[i]) continue

    let matchedLength = 0
    let matchedDefs: SignalDef[] | null = null

    for (let length = 4; length >= 1; length -= 1) {
      if (i + length > tokens.length) continue
      const phrase = tokens.slice(i, i + length).join(' ')
      const defs = SIGNALS.get(phrase)
      if (defs) {
        matchedLength = length
        matchedDefs = defs
        break
      }
    }

    if (matchedDefs && matchedLength > 0) {
      const negated = isNegated(tokens, i)
      for (const def of matchedDefs) dispatch(def, negated, out)
      for (let offset = 0; offset < matchedLength; offset += 1) consumed[i + offset] = true
    }
  }

  /* Whatever is left is either a Pokédex number or a free-text keyword. */
  for (let i = 0; i < tokens.length; i += 1) {
    if (consumed[i]) continue
    const token = tokens[i]

    if (/^\d{1,4}$/.test(token)) {
      const value = Number(token)
      if (value >= 1 && value <= 1026) pushUnique(out.numbers, value)
      continue
    }

    if (token.length < 3 || STOPWORDS.has(token)) continue
    if (isNegated(tokens, i)) pushUnique(out.excludeKeywords, singular(token))
    else pushUnique(out.keywords, singular(token))
  }

  out.rawTokens = tokens.filter(
    (token) => token.length >= 2 && !STOPWORDS.has(token) && !/^\d+$/.test(token),
  )

  return out
}

/** Folds a follow-up message into the accumulated description. */
export function mergeSignals(base: FinderSignals, delta: FinderSignals, replaceTypes = false): FinderSignals {
  const next: FinderSignals = {
    ...base,
    numbers: [...base.numbers],
    types: replaceTypes && delta.types.length > 0 ? [...delta.types] : [...base.types],
    excludeTypes: [...base.excludeTypes],
    color: delta.color ?? base.color,
    altColors: delta.color !== null ? [...delta.altColors] : [...base.altColors],
    excludeColors: [...base.excludeColors],
    shapes: delta.shapes.length > 0 ? [...delta.shapes] : [...base.shapes],
    excludeShapes: [...base.excludeShapes],
    features: [...base.features],
    keywords: [...base.keywords],
    excludeKeywords: [...base.excludeKeywords],
    legend: delta.legend ?? base.legend,
    rare: base.rare || delta.rare,
    generation: delta.generation ?? base.generation,
    habitat: delta.habitat ?? base.habitat,
    size: [...base.size],
    stats: [...base.stats],
    rawTokens: [...base.rawTokens],
  }

  if (!replaceTypes || delta.types.length === 0) {
    for (const value of delta.types) pushUnique(next.types, value)
  }
  for (const value of delta.excludeTypes) pushUnique(next.excludeTypes, value)
  for (const value of delta.excludeColors) pushUnique(next.excludeColors, value)
  for (const value of delta.excludeShapes) pushUnique(next.excludeShapes, value)
  for (const value of delta.features) pushUnique(next.features, value)
  for (const value of delta.keywords) pushUnique(next.keywords, value)
  for (const value of delta.excludeKeywords) pushUnique(next.excludeKeywords, value)
  for (const value of delta.numbers) pushUnique(next.numbers, value)
  for (const value of delta.rawTokens) pushUnique(next.rawTokens, value)

  for (const constraint of delta.size) {
    const existing = next.size.find((entry) => entry.axis === constraint.axis)
    if (existing) existing.dir = constraint.dir
    else next.size.push({ ...constraint })
  }
  for (const constraint of delta.stats) {
    const existing = next.stats.find((entry) => entry.stat === constraint.stat)
    if (existing) existing.dir = constraint.dir
    else next.stats.push({ ...constraint })
  }

  return next
}

export function isEmptySignals(signals: FinderSignals): boolean {
  return (
    signals.numbers.length === 0 &&
    signals.types.length === 0 &&
    signals.excludeTypes.length === 0 &&
    signals.color === null &&
    signals.shapes.length === 0 &&
    signals.features.length === 0 &&
    signals.keywords.length === 0 &&
    signals.legend === null &&
    !signals.rare &&
    signals.generation === null &&
    signals.habitat === null &&
    signals.size.length === 0 &&
    signals.stats.length === 0
  )
}

/** Human-readable chips so the reader can see how their words were read. */
export function describeSignals(signals: FinderSignals): string[] {
  const chips: string[] = []

  for (const type of signals.types) chips.push(`Type: ${formatName(type)}`)
  if (signals.color) chips.push(`Colour: ${formatName(signals.color)}`)
  for (const color of signals.altColors) chips.push(`Also ${formatName(color)}`)
  for (const shape of signals.shapes) chips.push(`Shape: ${formatName(shape)}`)
  for (const feature of signals.features) chips.push(`Feature: ${feature}`)
  for (const keyword of signals.keywords) chips.push(`Keyword: ${keyword}`)
  if (signals.legend) chips.push(formatName(signals.legend))
  if (signals.rare) chips.push('Rare')
  if (signals.generation) chips.push(`Generation ${signals.generation}`)
  if (signals.habitat) chips.push(`Habitat: ${formatName(signals.habitat)}`)
  for (const entry of signals.size) {
    const label =
      entry.axis === 'height'
        ? entry.dir === 'high'
          ? 'Tall'
          : 'Small'
        : entry.dir === 'high'
          ? 'Heavy'
          : 'Light'
    chips.push(label)
  }
  for (const entry of signals.stats) chips.push(statReason(entry))
  for (const number of signals.numbers) chips.push(`#${number}`)
  for (const type of signals.excludeTypes) chips.push(`Not ${formatName(type)}`)
  for (const color of signals.excludeColors) chips.push(`Not ${formatName(color)}`)
  for (const shape of signals.excludeShapes) chips.push(`Not ${formatName(shape)}`)
  for (const keyword of signals.excludeKeywords) chips.push(`Not ${keyword}`)

  return chips
}

function statReason(constraint: StatConstraint): string {
  switch (constraint.stat) {
    case 'speed':
      return constraint.dir === 'high' ? 'Fast' : 'Slow'
    case 'attack':
      return constraint.dir === 'high' ? 'Strong' : 'Weak'
    case 'specialAttack':
      return constraint.dir === 'high' ? 'Special attacker' : 'Low special attack'
    case 'defense':
      return constraint.dir === 'high' ? 'Tough' : 'Fragile'
    case 'specialDefense':
      return constraint.dir === 'high' ? 'Special wall' : 'Low special defense'
    case 'hp':
      return constraint.dir === 'high' ? 'High HP' : 'Low HP'
  }
}

/* ==========================================================================
   The engine
   ========================================================================== */

interface IndexedPokemon {
  pokemon: FinderPokemon
  tokens: Set<string>
  abilityTokens: Set<string>
}

const MIN_SCORE = 10
const MAX_REASONS = 4

function legendIncludes(pokemon: FinderPokemon, legend: Exclude<Legend, null>): boolean {
  if (legend === 'legendary') return pokemon.isLegendary
  if (legend === 'mythical') return pokemon.isMythical
  return pokemon.isBaby
}

function nameMatches(pokemon: FinderPokemon, rawTokens: string[]): boolean {
  const nameTokens = pokemon.name.split('-')
  if (nameTokens.length === 1) return rawTokens.includes(nameTokens[0])

  for (let i = 0; i + nameTokens.length <= rawTokens.length; i += 1) {
    let hit = true
    for (let j = 0; j < nameTokens.length; j += 1) {
      if (rawTokens[i + j] !== nameTokens[j]) {
        hit = false
        break
      }
    }
    if (hit) return true
  }
  return false
}

export class FinderEngine {
  private readonly entries: IndexedPokemon[]
  private readonly df = new Map<string, number>()
  private readonly total: number
  private readonly maxHeight: number
  private readonly maxWeight: number
  private readonly maxStat: Record<StatKey, number>

  constructor(pokemon: FinderPokemon[]) {
    this.total = pokemon.length
    this.maxHeight = Math.max(1, ...pokemon.map((p) => p.height))
    this.maxWeight = Math.max(1, ...pokemon.map((p) => p.weight))

    const statKeys: StatKey[] = ['hp', 'attack', 'defense', 'specialAttack', 'specialDefense', 'speed']
    this.maxStat = statKeys.reduce(
      (acc, key) => {
        acc[key] = Math.max(1, ...pokemon.map((p) => p.stats[key]))
        return acc
      },
      { hp: 1, attack: 1, defense: 1, specialAttack: 1, specialDefense: 1, speed: 1 },
    )

    this.entries = pokemon.map((entry) => {
      const abilityTokens = new Set<string>()
      for (const ability of entry.abilities) {
        for (const part of ability.split('-')) abilityTokens.add(singular(part))
      }

      const text = [
        entry.name,
        entry.name.replace(/-/g, ' '),
        entry.genus,
        entry.flavor,
        entry.types.join(' '),
        entry.abilities.map((ability) => ability.replace(/-/g, ' ')).join(' '),
        entry.color ?? '',
        entry.shape ?? '',
        entry.habitat ?? '',
      ].join(' ')

      const tokens = new Set<string>()
      for (const token of normalize(text).split(' ')) {
        if (!token) continue
        tokens.add(token)
        tokens.add(singular(token))
        this.df.set(token, (this.df.get(token) ?? 0) + 1)
      }

      return { pokemon: entry, tokens, abilityTokens }
    })
  }

  search(signals: FinderSignals, limit = 6): FinderMatch[] {
    if (isEmptySignals(signals)) return []

    let matches = this.run(signals, true)
    if (matches.length === 0) matches = this.run(signals, false)
    return matches.slice(0, limit)
  }

  countMatches(signals: FinderSignals): number {
    if (isEmptySignals(signals)) return 0
    const matches = this.run(signals, true)
    return (matches.length > 0 ? matches : this.run(signals, false)).length
  }

  private run(signals: FinderSignals, enforce: boolean): FinderMatch[] {
    const matches: FinderMatch[] = []

    for (const entry of this.entries) {
      const { pokemon, tokens, abilityTokens } = entry

      if (enforce) {
        if (signals.excludeTypes.some((type) => pokemon.types.includes(type))) continue
        if (signals.excludeShapes.some((shape) => pokemon.shape === shape)) continue
        if (signals.excludeColors.some((color) => pokemon.color === color)) continue
        if (signals.legend && !legendIncludes(pokemon, signals.legend)) continue
        if (signals.generation && pokemon.generation !== signals.generation) continue
      }

      let score = 0
      const reasons: string[] = []

      if (nameMatches(pokemon, signals.rawTokens)) {
        score += 120
        reasons.push('Name match')
      }
      if (signals.numbers.includes(pokemon.id)) {
        score += 200
        reasons.push('Pokédex number')
      }

      for (const type of signals.types) {
        if (pokemon.types.includes(type)) {
          score += 26
          reasons.push(`${formatName(type)} type`)
        }
      }

      if (signals.color && pokemon.color === signals.color) {
        score += 16
        reasons.push(`${formatName(signals.color)} colour`)
      }

      for (const altColor of signals.altColors) {
        if (pokemon.color === altColor) {
          score += 8
          reasons.push(`${formatName(altColor)} accent`)
        }
      }

      for (const shape of signals.shapes) {
        if (pokemon.shape === shape) {
          score += 20
          reasons.push(`${formatName(shape)} shape`)
        }
      }

      for (const feature of signals.features) {
        if (tokens.has(feature) || tokens.has(singular(feature))) {
          score += 14
          reasons.push(`Has ${feature}`)
        }
      }

      for (const keyword of signals.keywords) {
        if (abilityTokens.has(keyword)) {
          score += 24
          reasons.push(`Ability: ${formatName(keyword)}`)
          continue
        }
        if (tokens.has(keyword) || tokens.has(singular(keyword))) {
          const idf = Math.log(1 + this.total / (this.df.get(keyword) ?? 1))
          score += Math.min(4 + idf * 3, 18)
        }
      }

      for (const keyword of signals.excludeKeywords) {
        if (tokens.has(keyword)) score -= 12
      }

      for (const constraint of signals.size) {
        const value =
          constraint.axis === 'height'
            ? pokemon.height / this.maxHeight
            : pokemon.weight / this.maxWeight
        const strength = constraint.dir === 'high' ? value : 1 - value
        score += Math.round(strength * 16)
        if (strength > 0.55) {
          reasons.push(
            constraint.axis === 'height'
              ? constraint.dir === 'high'
                ? 'Tall'
                : 'Small'
              : constraint.dir === 'high'
                ? 'Heavy'
                : 'Light',
          )
        }
      }

      for (const constraint of signals.stats) {
        const value = pokemon.stats[constraint.stat] / this.maxStat[constraint.stat]
        const strength = constraint.dir === 'high' ? value : 1 - value
        score += Math.round(strength * 16)
        if (strength > 0.6) reasons.push(statReason(constraint))
      }

      if (signals.legend) {
        if (legendIncludes(pokemon, signals.legend)) {
          score += 30
          reasons.push(formatName(signals.legend))
        } else if (!enforce) {
          score -= 12
        }
      }

      if (signals.rare && (pokemon.isLegendary || pokemon.isMythical)) {
        score += 20
        reasons.push('Rare')
      }

      if (signals.generation) {
        if (pokemon.generation === signals.generation) {
          score += 25
          reasons.push(`Generation ${signals.generation}`)
        } else if (!enforce) {
          score -= 10
        }
      }

      if (signals.habitat && pokemon.habitat === signals.habitat) {
        score += 14
        reasons.push(`${formatName(signals.habitat)} habitat`)
      }

      if (score >= MIN_SCORE) {
        matches.push({ pokemon, score, reasons: dedupe(reasons).slice(0, MAX_REASONS) })
      }
    }

    matches.sort((a, b) => b.score - a.score || a.pokemon.id - b.pokemon.id)
    return matches
  }
}

function dedupe(values: string[]): string[] {
  return [...new Set(values)]
}
